  "privFooter": "Privatumas ir saugykla",
  "privTitle": "Privatumas ir naršyklės saugykla",
  "privClose": "Uždaryti privatumo pranešimą",
  "privWho": "Kas atsakingas?",
  "privWhat": "Ką naudojame ir kodėl",
