  "privProviders": "Paslaugų teikėjai ir tarptautinis duomenų perdavimas",
  "privRetention": "Saugojimas ir ištrynimas",
  "privRights": "Jūsų teisės",
  "noticeReopen": "Pranešimas apie saugyklą",
  "noticeLabel": "Pranešimas apie naršyklės saugyklą",
  "noticeText": "Cook naudoja naršyklės saugyklą jūsų naudojamoms gaminimo ir prisijungimo funkcijoms. Reklamos ar analitikos saugyklos nepridedama.",
  "noticeClose": "Uždaryti pranešimą apie saugyklą",
  "privDraftLabel": "Juodraštis – atnaujinta 2026 m. spalio 28 d.",
  "privDraft": "Paskyros funkcijos šiuo metu testuojamos. Toliau pateikti duomenys apie valdytoją ir paslaugas turi būti užpildyti prieš viešą paleidimą.",
  "privWho1": "Cook valdo [valdytojo teisinis pavadinimas ir pašto adresas]. Privatumo klausimais ir prašymais kreipkitės [privatumo el. pašto adresas]. Šie duomenys turi būti užpildyti prieš atidarant registraciją.",
  "privWhat1": "Kai sukuriate paskyrą, naudojame jūsų el. paštą, paskyros identifikatorių, autentifikavimo slaptažodžiu įrašus ir patvirtinimo būseną, kad teiktume ir apsaugotume jūsų paskyrą. Slaptažodžius autentifikavimo paslaugų teikėjas tvarko kaip saugias maišos reikšmes; Cook nesaugo įskaitomų slaptažodžių. Saugome jūsų virtuvės išdėstymą, pasirinktą kalbą, temą ir matavimo vienetus, kad atkurtume nustatymus visuose įrenginiuose. Paskyrai reikia el. pašto ir slaptažodžio; receptus galite naršyti ir be paskyros.",
  "privWhat2": "Paskyros ir nustatymų tvarkymas būtinas, kad teiktume jūsų prašomą paskyros paslaugą (BDAR 6 straipsnio 1 dalies b punktas). Riboti saugumo ir piktnaudžiavimo prevencijos įrašai gali būti tvarkomi remiantis teisėtais interesais (6 straipsnio 1 dalies f punktas), kiek tai būtina ir įvertinus interesų pusiausvyrą. Patvirtinimo ir slaptažodžio atkūrimo laiškai yra paslaugos pranešimai, o ne rinkodara. Paskyros funkcija neprideda reklamos ar analitikos.",
  "privStorage1": "Cook naudoja sessionStorage, kad jūsų virtuvė, gaminimo eiga ir pasirinkimai būtų perkelti tarp to paties skirtuko puslapių. Kai esate prisijungę, joje saugomas ir jūsų prisijungimo seansas. Naršyklė paprastai tai išvalo pasibaigus skirtuko seansui, tačiau naršyklės seanso atkūrimas gali tai išsaugoti. Atsijungus Cook skirtuko duomenys išvalomi. Pranešimo apie saugyklą uždarymas įsimenamas tik tame skirtuke. Paties Cook scenarijai nenustato slapukų. Jūsų prieglobos ar paslaugų teikėjai gali vykdyti savo saugumo tvarkymą, kuris turi būti dokumentuotas prieš paleidimą.",
  "privStorage2": "Gerai ir pranešimo apie saugyklą uždarymo mygtukas tik uždaro pranešimą. Jie neleidžia analitikos, reklamos ar kito neprivalomo sekimo. Bet kokiai būsimai nebūtinai saugyklai prieš jos pradžią reikės atskiro pasirinkimo, kai atsisakyti ir atšaukti būtų taip pat lengva.",
  "privOther1": "Dabartinė receptų sąrašo kalbos funkcija pagal jūsų IP adresą užklausia country.is apytikslės šalies, kad parinktų kalbos atpažinimo kalbą. Jei naudojate mikrofono atpažinimą, naršyklė gali siųsti garsą savo kalbos atpažinimo paslaugų teikėjui. Ingredientus galite ir įvesti. Šie teikėjai, jų politika ir šių funkcijų teisinis pagrindas turi būti peržiūrėti prieš viešą paleidimą.",
  "privProviders1": "Planuojamas paskyrų paslaugų teikėjas: Supabase (valdoma PostgreSQL ir autentifikavimas) su pasirinktu ES duomenų bazės regionu. El. pašto paslaugų teikėjas: [teikėjas]. Svetainės prieglobos teikėjas: [teikėjas]. Valdytojas turi patvirtinti faktinius teikėjus, duomenų tvarkymo sutartis, subtvarkytojus, žurnalų buvimo vietas ir bet kokį perdavimą už EEE ribų. ES duomenų bazės regionas savaime neatmeta tarptautinio perdavimo. Prireikus nurodykite taikomą sprendimą dėl tinkamumo arba sutartines apsaugos priemones ir kaip gauti jų kopiją.",
  "privRetention1": "Paskyros nustatymai saugomi, kol jūsų paskyra aktyvi. Ištrynimo galite prašyti per pirmiau nurodytą privatumo kontaktą. Prieš paleidimą valdytojas turi nustatyti atsakymo į ištrynimo prašymus tvarką, nepatvirtintų paskyrų galiojimo pabaigą ir saugumo žurnalų bei atsarginių kopijų saugojimo terminus. Ištrinti duomenys gali likti ribotos prieigos atsarginėse kopijose iki dokumentuoto saugojimo termino pabaigos.",
  "privRights1": "Priklausomai nuo taikomų sąlygų, galite prašyti susipažinti su duomenimis, juos ištaisyti, ištrinti, apriboti jų tvarkymą ar perkelti juos, arba nesutikti su tvarkymu, grindžiamu teisėtais interesais. Kreipkitės į pirmiau nurodytą valdytoją; į prašymus paprastai atsakoma per vieną mėnesį, o teisėtas termino pratęsimas paaiškinamas. Galite pateikti skundą priežiūros institucijai, įskaitant Vengrijos NAIH adresu naih.hu. Cook nenaudoja paskyros nustatymų automatizuotiems sprendimams, turintiems teisinių ar panašiai reikšmingų pasekmių.",
